query MarketAuditBasics($after: String) {
shop { id name primaryDomain { url } currencyCode enabledPresentmentCurrencies countriesInShippingZones { countryCodes includeRestOfWorld } shipsToCountries }
shopLocales { locale name primary published }
publications(first: 50, after: $after) { nodes { id autoPublish catalog { id title status __typename } includedProductsCount(query: "status:active") { count precision } } pageInfo { hasNextPage endCursor } }
