query MarketAudit($after: String) {
markets(first: 10, after: $after) {
nodes { id name handle status
conditions { conditionTypes regionsCondition { regions(first: 250) { nodes { __typename ... on MarketRegionCountry { code name currency { currencyCode enabled } } } pageInfo { hasNextPage endCursor } } } }
currencySettings { baseCurrency { currencyCode enabled } localCurrencies }
